function questionEditor(qid,q){let details=q.type==='choice'?area('Candidate key: meaning · one per line','criteria',Object.entries(q.criteria).map(([k,v])=>k+': '+(v||'')).join('\n'),'Use concise candidate labels; include a no-match option when needed.','3',qid):q.type==='score'?area('Ordered score levels · one description per line','criteria',q.criteria.join('\n'),'Describe concrete, ordered states; Score rubrics use 2–10 ordered levels.','3',qid):'<p class="subtle">Yes/no judgment. Use instructions to define what “yes” means.</p>';return '<div class="question-card"><div class="grid2">'+field('Question key','questionId',qid,'text','','',qid)+select('questionType',[{value:'choice',label:'Choice'},{value:'score',label:'Score'},{value:'noul',label:'Yes / no'}],q.type,'Answer type',qid)+'</div>'+field('Question label','questionLabel',q.label,'text','','',qid)+area('Instructions','questionInstructions',q.instructions,'Complete meaning is sent with each poll.','3',qid)+details+'<button type="button" class="button small danger" data-act="remove-question" data-id="'+attr(qid)+'">Remove question</button></div>'}
