function sourcesEditor(c){const rows=c.sources.map(s=>'<form data-form="source" data-id="'+attr(s.id)+'" class="item-card"><h3>'+esc(s.title||s.id)+'</h3><div class="grid2">'+field('Source ID','sourceId',s.id,'text','','',s.id)+field('Retrieved date','retrievedAt',(s.retrievedAt||'').slice(0,10),'date','','',s.id)+field('Title','sourceTitle',s.title,'text','','',s.id)+field('URL','sourceUrl',s.url,'url','','',s.id)+'</div>'+area('What this supports and its limitations','sourceNotes',s.notes,'','2',s.id)+'<div class="row"><button class="button small soft" type="submit">Apply source</button><button type="button" class="button small danger" data-act="remove-source" data-id="'+attr(s.id)+'">Remove source</button></div></form>').join('');return panel('Sources','Cite what supports the population, traits, and weights. The workspace does not verify claims.',rows+'<button type="button" class="button small" data-act="add-source">＋ Add source</button>')}
function segmentsEditor(c){const rows=c.segments.map(s=>'<form data-form="segment" data-id="'+attr(s.id)+'" class="item-card"><h3>'+esc(s.label||s.id)+'</h3><div class="grid3">'+field('Segment ID','segmentId',s.id,'text','','',s.id)+field('Label','segmentLabel',s.label,'text','','',s.id)+field('Population share','segmentWeight',s.weight,'number','','min="0" step="any"',s.id)+'</div>'+area('Description','segmentDescription',s.description,'','2',s.id)+'<div class="grid2">'+select('weightBasis',[{value:'sourced',label:'Source-backed'},{value:'assumed',label:'Assumed'},{value:'user',label:'User supplied'}],s.weightBasis,'Weight basis',s.id)+'<div class="field"><label>Sources</label><div class="condition">'+sourceChecks(c,s.sourceIds)+'</div></div></div><div class="row"><button class="button small soft" type="submit">Apply segment</button><button type="button" class="button small danger" data-act="remove-segment" data-id="'+attr(s.id)+'">Remove segment</button></div></form>').join('');return panel('Segments and weights','Shares describe the panel composition. Persona weights are within-segment weights.',rows+'<button type="button" class="button small" data-act="add-segment">＋ Add segment</button>')}
